import React from 'react';
import { AbsoluteFill, Sequence, interpolate, spring, useCurrentFrame, Easing } from 'remotion';

export default function ConceptExplainer({ scene, durF }: { scene: any; durF: number }) {
  const frame = useCurrentFrame();

  const conceptPositions: { [key: string]: { x: number; y: number } } = {}; // To store actual pixel positions after layout

  const getConceptStyle = (concept: any, index: number) => {
    const delay = concept.delay_frames || 0;
    const appearProgress = spring({
      frame: frame - delay,
      fps: 30,
      config: {
        damping: 200,
        stiffness: 100,
        mass: 0.5,
      },
      durationInFrames: 30,
    });

    const scale = interpolate(appearProgress, [0, 1], [0.5, 1]);
    const opacity = interpolate(appearProgress, [0, 1], [0, 1]);

    let xOffset = 0;
    let yOffset = 0;
    switch (concept.position) {
      case 'center': xOffset = 0; yOffset = 0; break;
      case 'left': xOffset = -400; yOffset = 0; break;
      case 'right': xOffset = 400; yOffset = 0; break;
      case 'top': xOffset = 0; yOffset = -250; break;
      case 'bottom': xOffset = 0; yOffset = 250; break;
    }

    // Store positions for connections (relative to center, then adjusted for screen size)
    // Assuming 1920x1080 screen, center is (960, 540)
    conceptPositions[concept.text] = { x: 960 + xOffset, y: 540 + yOffset };

    return {
      position: 'absolute' as const,
      left: '50%',
      top: '50%',
      transform: `translate(-50%, -50%) translate(${xOffset}px, ${yOffset}px) scale(${scale})`,
      opacity,
      fontSize: 60,
      fontWeight: 'bold' as const,
      color: concept.color,
      whiteSpace: 'nowrap' as const,
      textAlign: 'center' as const,
      padding: '20px 40px',
      borderRadius: 10,
      backgroundColor: 'rgba(0,0,0,0.5)',
      boxShadow: `0 0 20px ${concept.color}50`,
      zIndex: 2, // Concepts should be above lines
    };
  };

  const getConnectionStyle = (connection: any) => {
    const fromPos = conceptPositions[connection.from];
    const toPos = conceptPositions[connection.to];

    if (!fromPos || !toPos) return {};

    const delay = connection.delay_frames || 0;
    const drawProgress = spring({
      frame: frame - delay,
      fps: 30,
      config: {
        damping: 200,
        stiffness: 100,
        mass: 0.5,
      },
      durationInFrames: 30,
    });

    const x1 = fromPos.x;
    const y1 = fromPos.y;
    const x2 = toPos.x;
    const y2 = toPos.y;

    const pathD = `M ${x1} ${y1} L ${x2} ${y2}`;
    const length = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
    const strokeDashoffset = interpolate(drawProgress, [0, 1], [length, 0]);
    const opacity = interpolate(drawProgress, [0, 1], [0, 1]);


    return {
      pathD,
      length,
      strokeDashoffset,
      stroke: connection.color,
      opacity,
    };
  };

  const titleAppearProgress = spring({
    frame: frame,
    fps: 30,
    config: {
      damping: 200,
      stiffness: 100,
      mass: 0.5,
    },
    durationInFrames: 30,
  });

  const titleScale = interpolate(titleAppearProgress, [0, 1], [0.8, 1]);
  const titleOpacity = interpolate(titleAppearProgress, [0, 1], [0, 1]);
  const titleTranslateY = interpolate(titleAppearProgress, [0, 1], [-50, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: '#1A1A1A', justifyContent: 'center', alignItems: 'center' }}>
      {scene.title && (
        <div
          style={{
            position: 'absolute',
            top: 100,
            width: '100%',
            fontSize: 72,
            fontWeight: 'bold' as const,
            color: scene.title_color,
            opacity: titleOpacity,
            transform: `translateY(${titleTranslateY}px) scale(${titleScale})`,
            textAlign: 'center' as const,
            zIndex: 10,
          }}
        >
          {scene.title}
        </div>
      )}

      <svg width="100%" height="100%" style={{ position: 'absolute', zIndex: 1 }}>
        {scene.connections.map((connection: any, i: number) => {
          const { pathD, length, strokeDashoffset, stroke, opacity } = getConnectionStyle(connection);
          return (
            <path
              key={i}
              d={pathD}
              stroke={stroke}
              strokeWidth="10"
              fill="none"
              strokeDasharray={length}
              strokeDashoffset={strokeDashoffset}
              strokeLinecap="round"
              style={{ opacity }}
            />
          );
        })}
      </svg>

      {scene.concepts.map((concept: any, i: number) => (
        <div key={i} style={getConceptStyle(concept, i)}>
          {concept.text}
        </div>
      ))}
    </AbsoluteFill>
  );
}

