import React from 'react';
import { AbsoluteFill, Sequence, interpolate, spring, useCurrentFrame, Easing } from 'remotion';

export default function TaskOffloader({ scene, durF }: { scene: any; durF: number }) {
  const frame = useCurrentFrame();

  const humanAppearProgress = spring({
    frame: frame,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 30,
  });
  const humanScale = interpolate(humanAppearProgress, [0, 1], [0.5, 1]);
  const humanOpacity = interpolate(humanAppearProgress, [0, 1], [0, 1]);
  const humanTranslateX = interpolate(humanAppearProgress, [0, 1], [-200, -400]);

  const taskAppearProgress = spring({
    frame: frame - 30,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 30,
  });
  const taskOpacity = interpolate(taskAppearProgress, [0, 1], [0, 1]);
  const taskTranslateY = interpolate(taskAppearProgress, [0, 1], [50, 0]);

  const softwareAppearProgress = spring({
    frame: frame - 90,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 30,
  });
  const softwareScale = interpolate(softwareAppearProgress, [0, 1], [0.5, 1]);
  const softwareOpacity = interpolate(softwareAppearProgress, [0, 1], [0, 1]);
  const softwareTranslateX = interpolate(softwareAppearProgress, [0, 1], [200, 400]);

  const arrowDrawProgress = spring({
    frame: frame - 120,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 45,
  });

  const arrowLength = 800; // Distance between human and software
  const arrowOffset = interpolate(arrowDrawProgress, [0, 1], [arrowLength, 0]);

  const textAppearProgress = spring({
    frame: frame - 180,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 30,
  });
  const textScale = interpolate(textAppearProgress, [0, 1], [0.8, 1]);
  const textOpacity = interpolate(textAppearProgress, [0, 1], [0, 1]);

  return (
    <AbsoluteFill style={{ backgroundColor: '#1A1A1A', justifyContent: 'center', alignItems: 'center' }}>
      <div
        style={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          transform: `translate(-50%, -50%) translateX(${humanTranslateX}px) scale(${humanScale})`,
          opacity: humanOpacity,
          width: 200,
          height: 200,
          borderRadius: '50%',
          backgroundColor: '#FFC107',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          boxShadow: '0 0 30px rgba(255,193,7,0.5)',
          zIndex: 2,
        }}
      >
        {/* Abstract human icon */}
        <svg width="100" height="100" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#333' }}>
          <circle cx="12" cy="7" r="4"></circle>
          <path d="M12 14s-2 2-4 2-4-2-4-2"></path>
          <path d="M12 14s2 2 4 2 4-2 4-2"></path>
          <path d="M16 17l-1 4"></path>
          <path d="M8 17l1 4"></path>
        </svg>
      </div>
      <div
        style={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          transform: `translate(-50%, -50%) translateX(${humanTranslateX}px) translateY(${150 + taskTranslateY}px)`,
          opacity: taskOpacity,
          fontSize: 40,
          color: '#E0E0E0',
          zIndex: 2,
        }}
      >
        Tedious Tasks
      </div>

      <svg width="100%" height="100%" style={{ position: 'absolute', zIndex: 1 }}>
        <line
          x1="calc(50% - 300px)" y1="50%" x2="calc(50% + 300px)" y2="50%"
          stroke="#4CAF50" strokeWidth="10" strokeDasharray={arrowLength} strokeDashoffset={arrowOffset}
          markerEnd="url(#arrowhead)"
          style={{ opacity: interpolate(arrowDrawProgress, [0, 1], [0, 1]) }}
        />
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="0" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#4CAF50" />
          </marker>
        </defs>
      </svg>

      <div
        style={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          transform: `translate(-50%, -50%) translateX(${softwareTranslateX}px) scale(${softwareScale})`,
          opacity: softwareOpacity,
          width: 300,
          height: 200,
          borderRadius: 15,
          backgroundColor: '#2196F3',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          boxShadow: '0 0 30px rgba(33,150,243,0.5)',
          zIndex: 2,
        }}
      >
        {/* Generic software icon */}
        <svg width="120" height="120" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#FFF' }}>
          <rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect>
          <line x1="8" y1="21" x2="16" y2="21"></line>
          <line x1="12" y1="17" x2="12" y2="21"></line>
        </svg>
      </div>

      <div
        style={{
          position: 'absolute',
          bottom: 100,
          fontSize: 60,
          color: '#FFFFFF',
          opacity: textOpacity,
          transform: `scale(${textScale})`,
          textAlign: 'center',
          width: '80%',
          zIndex: 3,
        }}
      >
        Offloading repetitive tasks to software.
      </div>
    </AbsoluteFill>
  );
}

