import React from 'react';
import { AbsoluteFill, Sequence, interpolate, spring, useCurrentFrame, Easing } from 'remotion';

const Node = ({ text, color, delay, x, y }: { text: string; color: string; delay: number; x: number; y: number }) => {
  const frame = useCurrentFrame();
  const appearProgress = spring({
    frame: frame - delay,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 30,
  });
  const scale = interpolate(appearProgress, [0, 1], [0.5, 1]);
  const opacity = interpolate(appearProgress, [0, 1], [0, 1]);

  return (
    <div
      style={{
        position: 'absolute',
        left: x,
        top: y,
        transform: `translate(-50%, -50%) scale(${scale})`,
        opacity,
        backgroundColor: '#282C34',
        border: `2px solid ${color}`,
        borderRadius: 8,
        padding: '15px 25px',
        color: '#FFFFFF',
        fontSize: 36,
        fontWeight: 'bold',
        boxShadow: `0 0 15px ${color}50`,
        whiteSpace: 'nowrap',
        zIndex: 2,
      }}
    >
      {text}
    </div>
  );
};

const Connection = ({ fromX, fromY, toX, toY, delay, color }: { fromX: number; fromY: number; toX: number; toY: number; delay: number; color: string }) => {
  const frame = useCurrentFrame();
  const drawProgress = spring({
    frame: frame - delay,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 45,
  });

  const pathD = `M ${fromX} ${fromY} L ${toX} ${toY}`;
  const length = Math.sqrt(Math.pow(toX - fromX, 2) + Math.pow(toY - fromY, 2));
  const strokeDashoffset = interpolate(drawProgress, [0, 1], [length, 0]);
  const opacity = interpolate(drawProgress, [0, 1], [0, 1]);

  return (
    <svg style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', zIndex: 1 }}>
      <defs>
        <marker id="arrowhead_n8n" markerWidth="10" markerHeight="7" refX="0" refY="3.5" orient="auto">
          <polygon points="0 0, 10 3.5, 0 7" fill={color} />
        </marker>
      </defs>
      <path
        d={pathD}
        stroke={color}
        strokeWidth="8"
        fill="none"
        strokeDasharray={length}
        strokeDashoffset={strokeDashoffset}
        strokeLinecap="round"
        markerEnd="url(#arrowhead_n8n)"
        style={{ opacity }}
      />
    </svg>
  );
};

export default function N8nEmailAiWorkflowDemo({ scene, durF }: { scene: any; durF: number }) {
  const nodes = [
    { id: 'email', text: 'Email Received', color: '#FFC107', x: 400, y: 540, delay: 0, width: 250 }, // Estimated width
    { id: 'ai', text: 'AI Process', color: '#2196F3', x: 800, y: 540, delay: 60, width: 200 },
    { id: 'record', text: 'Record Data', color: '#4CAF50', x: 1200, y: 540, delay: 120, width: 220 },
    { id: 'respond', text: 'Send Response', color: '#E91E63', x: 1600, y: 540, delay: 180, width: 260 },
  ];

  const connections = [
    { from: 'email', to: 'ai', color: '#FFC107', delay: 90 },
    { from: 'ai', to: 'record', color: '#2196F3', delay: 150 },
    { from: 'record', to: 'respond', color: '#4CAF50', delay: 210 },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: '#1A1A1A', justifyContent: 'center', alignItems: 'center' }}>
      <div style={{ position: 'absolute', top: 100, fontSize: 72, fontWeight: 'bold', color: '#FFFFFF', zIndex: 3, opacity: spring({ frame: useCurrentFrame(), fps: 30, durationInFrames: 30 }) }}>
        N8N Workflow Example
      </div>
      {nodes.map((node) => (
        <Node key={node.id} text={node.text} color={node.color} delay={node.delay} x={node.x} y={node.y} />
      ))}
      {connections.map((conn, i) => {
        const fromNode = nodes.find(n => n.id === conn.from);
        const toNode = nodes.find(n => n.id === conn.to);
        if (!fromNode || !toNode) return null;
        return (
          <Connection
            key={i}
            fromX={fromNode.x + fromNode.width / 2 - 25} // Connect from right edge of source node (minus padding)
            fromY={fromNode.y}
            toX={toNode.x - toNode.width / 2 + 25} // Connect to left edge of target node (minus padding)
            toY={toNode.y}
            delay={conn.delay}
            color={conn.color}
          />
        );
      })}
    </AbsoluteFill>
  );
}

