import React from 'react';
import { AbsoluteFill, Sequence, interpolate, spring, useCurrentFrame, Easing } from 'remotion';

const ToolIcon = ({ delay, x, y, icon, label, color }: { delay: number; x: number; y: number; icon: string; label: string; color: string }) => {
  const frame = useCurrentFrame();
  const appearProgress = spring({
    frame: frame - delay,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 30,
  });
  const scale = interpolate(appearProgress, [0, 1], [0.5, 1]);
  const opacity = interpolate(appearProgress, [0, 1], [0, 1]);

  return (
    <div
      style={{
        position: 'absolute',
        left: x,
        top: y,
        transform: `translate(-50%, -50%) scale(${scale})`,
        opacity,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        color: '#FFFFFF',
        fontSize: 30,
        zIndex: 2,
      }}
    >
      <div
        style={{
          width: 100,
          height: 100,
          borderRadius: '50%',
          backgroundColor: color,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          marginBottom: 10,
          boxShadow: `0 0 15px ${color}50`,
