};

export default function EngineerMindsetExplainer({ scene, durF }: { scene: any; durF: number }) {
  const frame = useCurrentFrame();

  const titleAppearProgress = spring({
    frame: frame,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
    durationInFrames: 30,
  });
  const titleScale = interpolate(titleAppearProgress, [0, 1], [0.8, 1]);
  const titleOpacity = interpolate(titleAppearProgress, [0, 1], [0, 1]);

  const arrowDrawProgress = spring({
    frame: frame - 100,
    fps: 30,
    config: { damping: 200, stiffness: 100, mass: 0.5 },
