          position: 'absolute',
          bottom: 150,
          fontSize: 60,
          fontWeight: 'bold',
          color: '#E0E0E0',
          opacity: mindsetTextOpacity,
          transform: `scale(${mindsetTextScale})`,
          textAlign: 'center',
          width: '80%',
          zIndex: 3,
